        assert!(!is_strict_cmd_w(CMD | SHIFT | OPTION, "w"), "Cmd+Shift+Option+W must NOT match");

        // Wrong characters
        assert!(!is_strict_cmd_w(CMD, "t"), "Cmd+T must NOT match");
        assert!(!is_strict_cmd_w(CMD, "q"), "Cmd+Q must NOT match");
        assert!(!is_strict_cmd_w(0, "w"), "Plain 'w' without Cmd must NOT match");
    }
}
